#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import {fileURLToPath} from "node:url";
import {createHash} from "node:crypto";
import {parseCsv,buildStationContext} from "./station_context.mjs";
import {toCsv} from "./watershed_join.mjs";
const root=path.dirname(fileURLToPath(import.meta.url));
const args=process.argv.slice(2);
if(args.some(x=>x!=="--check"))throw Error("Usage: node rebuild_station_context.mjs [--check]");
const hash=body=>createHash("sha256").update(body).digest("hex");
const read=name=>{
  const file=path.resolve(root,name);
  if(!file.startsWith(root+path.sep))throw Error("Original source leaves component");
  return fs.readFileSync(file);
};
const original=JSON.parse(read("model-sources.json"));
const expected=JSON.parse(read("station-context.sources.json")).entries[0];
const selected=original.entries.filter(e=>e.kind==="table"&&e.path==="derived/polygon_matches.csv"
  &&e.sha256===expected.metadata.original_polygon_table_sha256);
if(selected.length!==1)throw Error("Select one original complete WBD polygon table");
const source=selected[0];
for(const item of [source,...source.companions]){
  const body=read(item.path);
  if(hash(body)!==item.sha256 || (item.bytes!==undefined&&body.length!==item.bytes))
    throw Error("Original source differs: "+item.path);
}
const rows=parseCsv(read(source.path).toString("utf8"));
const context=buildStationContext(rows,source.sha256);
const output=Buffer.from(toCsv(context),"utf8");
if(context.length!==expected.metadata.row_count||hash(output)!==expected.sha256||output.length!==expected.bytes)
  throw Error("Station context differs from the retained complete source edition");
if(args.includes("--check")){
  if(!read(expected.path).equals(output))throw Error("Saved station context differs");
}else{
  const target=path.resolve(root,expected.path);
  if(!target.startsWith(root+path.sep))throw Error("Context output leaves component");
  fs.mkdirSync(path.dirname(target),{recursive:true});
  const staging=target+".building-"+process.pid;
  fs.writeFileSync(staging,output);fs.renameSync(staging,target);
}
console.log(JSON.stringify({original_rows:rows.length,station_context_rows:context.length,
  station_count:new Set(context.map(row=>row.station_id)).size,
  original_polygon_table_sha256:source.sha256,context_sha256:hash(output),
  original_coordinate_variants:[...new Set(context.map(row=>row.coordinate_variant))],
  role:"station location context",observation_rows_added:0},null,2));

#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";
import { fileURLToPath } from "node:url";
import { buildObservationWatershedJoin, toCsv } from "./watershed_join.mjs";
const root=path.dirname(fileURLToPath(import.meta.url));
const read=(relative)=>fs.readFileSync(path.resolve(root,relative),"utf8");
const hash=s=>createHash("sha256").update(s,"utf8").digest("hex");
const plan=JSON.parse(read("query-plan.json"));
const index=JSON.parse(read("capture-index.json"));
for(const input of plan.inputs){
 const text=read("inputs/"+input.path);
 if(Buffer.byteLength(text)!==input.bytes||hash(text)!==input.sha256)throw Error("Original input hash mismatch: "+input.path);
}
const captures=index.captures.map(c=>{
 const content=read(c.path.replace(/^observations\/wbd_station_join_20261013\//,""));
 if(Buffer.byteLength(content)!==c.bytes||hash(content)!==c.sha256)throw Error("Original response hash mismatch: "+c.path);
 return {...c,content};
});
const joined=buildObservationWatershedJoin(plan.points,captures,plan.domain_ids);
const outputs={"derived/point_watersheds.csv":toCsv(joined.pointRows),"derived/polygon_matches.csv":toCsv(joined.matchRows),"derived/summary.json":JSON.stringify(joined.summary,null,2)+"\n"};
const check=process.argv.includes("--check");
for(const [relative,text] of Object.entries(outputs)){
 if(check){if(read(relative)!==text)throw Error("Derived output differs: "+relative);}
 else {fs.mkdirSync(path.dirname(path.join(root,relative)),{recursive:true});fs.writeFileSync(path.join(root,relative),text,"utf8");}
}
console.log(JSON.stringify({operation:check?"verified_rebuild":"rebuilt",completed_points:joined.summary.completed_point_count,input_points:joined.summary.input_point_count,captured_geometries:joined.summary.captured_geometry_count,pending_points:joined.summary.pending_point_ids.length,files:Object.entries(outputs).map(([path,text])=>({path,bytes:Buffer.byteLength(text),sha256:hash(text)}))},null,2));

// Original WBD records become station context without changing observations or geometry.
export function parseCsv(text) {
  const rows=[]; let row=[],cell="",quoted=false;
  for(let i=0;i<text.length;i++){
    const ch=text[i];
    if(quoted){
      if(ch==='"' && text[i+1]==='"'){cell+='"';i++;}
      else if(ch==='"')quoted=false;
      else cell+=ch;
    } else if(ch==='"')quoted=true;
    else if(ch===','){row.push(cell);cell="";}
    else if(ch==='\n'||ch==='\r'){
      if(ch==='\r'&&text[i+1]==='\n')i++;
      row.push(cell);if(row.some(value=>value!==""))rows.push(row);
      row=[];cell="";
    } else cell+=ch;
  }
  if(quoted)throw Error("Incomplete original CSV quotation");
  if(row.length||cell){row.push(cell);rows.push(row);}
  if(!rows.length)throw Error("Choose the original populated WBD table");
  const fields=rows.shift();
  if(new Set(fields).size!==fields.length)throw Error("Repeated original WBD field");
  return rows.map(row=>{
    if(row.length!==fields.length)throw Error("Original WBD row width differs");
    return Object.fromEntries(fields.map((field,index)=>[field,row[index]]));
  });
}
export function buildStationContext(rows, sourceSha256) {
  if(!/^[0-9a-f]{64}$/.test(sourceSha256))throw Error("Retain the original polygon table hash");
  const identities=new Set();
  return rows.map((original,index)=>{
    if(!original.point_id||!original.entity_id)throw Error("Original WBD identity missing");
    const identity=JSON.stringify([original.point_id,original.response_feature_index]);
    if(identities.has(identity))throw Error("Repeated original WBD point/polygon row");
    identities.add(identity);
    let station=original.entity_id;
    if(original.point_kind==="npdes_outfall"){
      const match=/^(SC\d{7}):([^:]+)$/.exec(station);
      if(!match)throw Error("Original permit/outfall identity differs");
      station=match[1];
    } else if(!["assessment_station","usgs_gauge","study_station"].includes(original.point_kind))
      throw Error("Unrecognized original observation location kind");
    if(original.point_kind==="usgs_gauge"&&!/^USGS-\d+$/.test(station))
      throw Error("Preserve the original USGS station prefix");
    if("station_id" in original||"context_record_id" in original||"context_kind" in original)
      throw Error("Original context field would be overwritten");
    return {station_id:station,context_record_id:sourceSha256+":"+(index+1),
      context_kind:"original_point_wbd_polygon_match",...original};
  });
}

